declare(strict_types=1);

namespace LibreCode\AnsibleDocker\Tests\Talk\Media;

use Amp\Pipeline\DisposedException;
use Revolt\EventLoop;
use Webrtc\Codecs\EncodedPacket;
use Webrtc\RTP\Enum\MediaKind;
use Webrtc\RTP\MediaStreamTrack\MediaStreamTrack;

use function Amp\delay;

final class SyntheticMediaTrack extends MediaStreamTrack
{
    // One 16x16 black keyframe generated by FFmpeg/libvpx (IVF frame payload).
    public const VP8_KEYFRAME_BASE64 = 'EAIAnQEqEAAQAABHCIWFiJmEiAICAAwNYAD+/6tQgA==';
    public function __construct(MediaKind $kind)
    {
        parent::__construct($kind);
        EventLoop::queue(function () use ($kind): void {
            $timestamp = 0;
            while (!$this->isEnded()) {
                // A valid Opus silence frame and a real VP8 keyframe; no codec runtime needed.
                $frame = $kind === MediaKind::Audio
                    ? new EncodedPacket("\xf8\xff\xfe", $timestamp, audioLevel: 127, mimeType: 'audio/opus')
                    : new EncodedPacket(base64_decode(self::VP8_KEYFRAME_BASE64, true), $timestamp, mimeType: 'video/VP8');
                try {
                    $this->push($frame);
                } catch (DisposedException) {
                    return;
                }
                $timestamp += $kind === MediaKind::Audio ? 960 : 3000;
                delay(0.04);
            }
        });
    }
}
